  "arguments": "{\"file_path\": \"C:\\\\Users\\\\DELL\\\\AppData\\\\Local\\\\Temp\\\\arena-dsh-workspace-72477eaf-v9kze90d\\\\open-test-windows.ps1\", \"content\": \"# Open 100 native test windows, keep them open ~10 seconds, then close only these windows.\\n$ErrorActionPreference = 'Stop'\\n\\nAdd-Type -AssemblyName System.Windows.Forms\\nAdd-Type -AssemblyName System.Drawing\\n\\n$screen = [System.Windows.Forms.Screen]::PrimaryScreen\\n$bounds = $screen.WorkingArea\\n$winW = [int][math]::Floor($bounds.Width / 2)\\n$winH = [int][math]::Floor($bounds.Height / 2)\\n\\n$rng = [System.Random]::new()\\n$windows = [System.Collections.Generic.List[System.Windows.Forms.Form]]::new()\\n\\nfor ($i = 0; $i -lt 100; $i++) {\\n    $form = [System.Windows.Forms.Form]::new()\\n    $form.Text = \\\"Test Window $($i + 1)\\\"\\n    $form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedSingle\\n    $form.Size = [System.Drawing.Size]::new($winW, $winH)\\n\\n    $maxX = $bounds.Width - $winW\\n    $maxY = $bounds.Height - $winH\\n    $x = if ($maxX -gt 0) { $rng.Next(0, $maxX) } else { 0 }\\n    $y = if ($maxY -gt 0) { $rng.Next(0, $maxY) } else { 0 }\\n\\n    $form.StartPosition = [System.Windows.Forms.FormStartPosition]::Manual\\n    $form.Location = [System.Drawing.Point]::new($bounds.Left + $x, $bounds.Top + $y)\\n    $form.BackColor = [System.Drawing.Color]::FromArgb($rng.Next(256), $rng.Next(256), $rng.Next(256))\\n\\n    $windows.Add($form)\\n    $form.Show()\\n    [System.Windows.Forms.Application]::DoEvents()\\n}\\n\\n# Keep the windows alive and responsive for 10 seconds.\\n$start = [DateTime]::UtcNow\\nwhile (([DateTime]::UtcNow - $start).TotalSeconds -lt 10) {\\n    [System.Windows.Forms.Application]::DoEvents()\\n    Start-Sleep -Milliseconds 20\\n}\\n\\n# Close only the windows this script created.\\n$closed = 0\\nforeach ($form in $windows) {\\n    if (-not $form.IsDisposed) {\\n        $form.Close()\\n        $closed++\\n    }\\n}\\n[System.Windows.Forms.Application]::DoEvents()\\n\\nWrite-Output (\\\"Opened {0} windows ({1}x{2}), kept them open ~10 seconds, closed {3} of them.\\\" -f $windows.Count, $winW, $winH, $closed)\\n\"}"
